import{_ as n,l as o,o as e,c as s,v as t,p as l,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"斐波那契堆","description":"","frontmatter":{"title":"斐波那契堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fibonacci-heap.md","filePath":"cs/fibonacci-heap.md","lastUpdated":1789023840000}'),m={name:"cs/fibonacci-heap.md"};function h(_,a,E,f,A,b){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="斐波那契堆" tabindex="-1">斐波那契堆 <a class="header-anchor" href="#斐波那契堆" aria-label="Permalink to &quot;斐波那契堆&quot;">​</a></h1><div class="epigraph"><p>减键只把节点割下挂到根表，摊还 $O(1)$；代价堆在 extract-min 的Consolidate 上，用度数与标记限制树的形状。</p><footer>—— 据 Fredman and Tarjan, Fibonacci Heaps and Their Uses in Improved Network Optimization Algorithms, JACM 1987；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/leftist-pairing-heap">上一课</a>给出可并与实践中的配对堆。Dijkstra 一类算法要很多次 <code>decrease-key</code>，数组堆每次 \\(\\Theta(\\log n)\\)。本课不重写 npl。缺口是斐波那契堆：摊还 \\(O(1)\\) insert/meld/decrease-key，\\(O(\\log n)\\) extract-min，从而堆优化最短路的理论界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需要优先队列支持减键。二叉堆减键 \\(\\Theta(\\log n)\\)。斐波那契堆：根是循环链表；每棵树近似「度数 \\(d\\) 则规模至少 \\(F_{d+2}\\)」（斐波那契增长），故最大度数 \\(O(\\log n)\\)。decrease-key：降低键，若破坏堆序则割下该节点到根表，父若已标记则级联割。extract-min：删最小根，孩子变根，再按度数合并（consolidate）。缺口是<strong>把形状约束推迟到 extract-min</strong>，让减键走快捷路径。</p><p><span class="marginnote">CLRS 第 19 章是标准写法。标记表示「已经丢过一个孩子」；再丢则级联，保证度数–规模的斐波那契关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>insert：新节点入根表，更新 min 指针。meld：链两根表。decrease-key：如上割。势能：根数 + 两倍标记数，使级联割的摊还为 \\(O(1)\\)。</p>',8)),(e(),l(p,null,{default:i(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22decrease-key%22%5D%20--%3E%20CUT%5B%22%E5%89%B2%E5%88%B0%E6%A0%B9%E8%A1%A8%22%5D%0A%20%20CUT%20--%3E%20CAS%5B%22%E7%88%B6%E5%B7%B2%E6%A0%87%E8%AE%B0%E5%88%99%E7%BA%A7%E8%81%94%22%5D%0A%20%20EX%5B%22extract-min%22%5D%20--%3E%20CONS%5B%22%E6%8C%89%E5%BA%A6%E6%95%B0%E5%90%88%E5%B9%B6%E6%A0%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与配对堆：斐波那契常数大（指针多、consolidate），实践常输；理论界清楚。不要把 \\(O(1)\\) 写成最坏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Dijkstra + Fib 堆：\\(O(m+n\\log n)\\)。这是本课对算法课的接口，不在这里再推最短路正确性。空间每个节点若干指针与度数、标记，比二叉堆厚。</p><p>实现陷阱：循环链表边界、consolidate 数组按度数索引。教学以不变量为主，不要求交一份无 bug 代码当作业唯一解。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把严格 Fibonacci 堆或 rank-pairing 的全部变体写完。最坏 \\(O(1)\\) 减键是 Brodal 等另一结构，点名即可。下一课二项堆：更早、形状更规则的可并堆，便于理解「按秩合并」。</p><p>后课默认：理论减键用 Fib 堆说话。教学与实现可退回配对或二项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fibonacci 堆：摊还 \\(O(1)\\) 减键与 meld，\\(O(\\log n)\\) extract-min。</li><li>标记与级联割维持度数–规模。</li><li>实践常数大；二项堆形状更干净。</li><li>出处：Fredman and Tarjan, <em>JACM</em>, 1987；Cormen et al. 第 19 章。</li></ul>',9))])}const T=n(m,[["render",h]]);export{B as __pageData,T as default};
